public class ResourceRequirementsSanitizer {

  private ResourceRequirementsSanitizer() {}

  public static void sanitizeResourceRequirements(final Map<String, Object> actualMap,
      final PodTemplateSpec actualTemplate, final PodTemplateSpec desiredTemplate) {
    if (actualTemplate == null || desiredTemplate == null) {
      return;
    }
    final var actualPodSpec = actualTemplate.getSpec();
    final var desiredPodSpec = desiredTemplate.getSpec();
    if (actualPodSpec == null || desiredPodSpec == null) {
      return;
    }
    sanitizeResourceRequirements(actualMap, actualPodSpec.getContainers(),
        desiredPodSpec.getContainers(), "containers");
    sanitizeResourceRequirements(actualMap, actualPodSpec.getInitContainers(),
        desiredPodSpec.getInitContainers(), "initContainers");
  }

  private static void sanitizeResourceRequirements(final Map<String, Object> actualMap,
      final List<Container> actualContainers, final List<Container> desiredContainers,
      final String containerPath) {
    // sizes may be null when there are no (init)containers at all
    final int actualSize = actualContainers == null ? 0 : actualContainers.size();
    final int desiredSize = desiredContainers == null ? 0 : desiredContainers.size();
    if (actualSize != desiredSize) {
      return;
    }
    for (int i = 0; i < actualSize; i++) {
      final var actualContainer = actualContainers.get(i);
      final var desiredContainer = desiredContainers.get(i);
      if (!actualContainer.getName().equals(desiredContainer.getName())) {
        return;
      }
      final ResourceRequirements actualResources = actualContainer.getResources();
      final ResourceRequirements desiredResources = desiredContainer.getResources();
      if (actualResources == null || desiredResources == null) {
        return;
      }
      sanitizeQuantities(actualMap, actualResources.getRequests(), desiredResources.getRequests(),
          containerPath, i, "requests");
      sanitizeQuantities(actualMap, actualResources.getLimits(), desiredResources.getLimits(),
          containerPath, i, "limits");
    }
  }

  private static void sanitizeQuantities(final Map<String, Object> actualMap,
      final Map<String, Quantity> actualResource, final Map<String, Quantity> desiredResource,
      final String containerPath, final int containerIndex, final String resourceType) {
    if (actualResource == null || desiredResource == null
        || actualResource.size() != desiredResource.size()) {
      return;
    }
    for (final var actualEntry : actualResource.entrySet()) {
      final var resourceName = actualEntry.getKey();
      // ignore modified container resource requests or limits
      if (!desiredResource.containsKey(resourceName)) {
        return;
      }
      final var actualQuantity = actualEntry.getValue();
      final var desiredQuantity = desiredResource.get(resourceName);
      // only sanitize the actual quantity if it is numerically equal to the desired quantity, but
      // it is expressed with a different string representation
      if (actualQuantity.toString().equals(desiredQuantity.toString())
          || actualQuantity.getNumericalAmount()
              .compareTo(desiredQuantity.getNumericalAmount()) != 0) {
        continue;
      }
      updateActualResource(actualMap, containerPath, containerIndex, resourceType, resourceName,
